async function createUser(){const name=$('#rName').value.trim(),email=$('#rEmail').value.trim().toLowerCase(),phone=$('#rPhone').value.trim(),pass=$('#rPass').value;if(!name||!email||!phone||!pass)return toast('Preencha todos os campos.');if(pass.length<4)return toast('A senha precisa ter pelo menos 4 caracteres.');if(pass!==$('#rConfirm').value)return toast('As senhas não conferem.');if(!$('#rTerms').checked)return toast('Aceite os termos para continuar.');const users=read(K.users,[]);if(users.some(u=>norm(u.email)===norm(email)))return toast('Este e-mail já está cadastrado.');const u={id:'u-'+Date.now(),name,email,passwordHash:await hashPassword(pass),phone:phone.replace(/\D/g,''),role:'USER',course:'Aluno',campus:'Fatec Taquaritinga',active:true};users.push(u);write(K.users,users);setSession(u);go('home');toast('Conta criada com sucesso.')}
