async function resetPassword(){const email=norm($('#fEmail').value),users=read(K.users,[]),u=users.find(x=>norm(x.email)===email&&x.role==='USER');if(!u)return toast('E-mail não encontrado.');if($('#fPass').value.length<4)return toast('A nova senha precisa ter pelo menos 4 caracteres.');u.passwordHash=await hashPassword($('#fPass').value);write(K.users,users);go('login');toast('Senha redefinida.')}
