  $('#anfSave').onclick=()=>{const title=$('#anfTitle').value.trim(),desc=$('#anfDesc').value.trim(),cat=$('#anfCat').value,date=$('#anfDate').value,location=$('#anfLoc').value;if(!window.__adminNewPhoto)return toast('Adicione uma foto.');if(!title||!desc||!date||!location)return toast('Preencha todos os campos.');const items=read(K.items,[]);if(items.some(i=>norm(i.title)===norm(title)&&i.category===cat&&i.date===date&&norm(i.location)===norm(location)))return toast('Já existe um registro idêntico.');items.unshift({id:'item-admin-'+Date.now(),creatorId:currentUser().id,title,description:desc,category:cat,date,location,holder:'FATEC',status:'Em aberto',photos:[window.__adminNewPhoto],createdAt:nowISO(),returnInfo:null});write(K.items,items);closeModal();route()==='admin-dashboard'?adminDashboard():adminFound();toast('Item publicado com sucesso.')};
