  $$('[data-recover-lost]').forEach(b=>b.onclick=()=>recoverLostModal(b.dataset.recoverLost));if($('#exportLost'))$('#exportLost').onclick=()=>downloadJSON('itens-perdidos.json',read(K.lost,[]));
