function recoverLostModal(id){
  const lost=read(K.lost,[]),request=lost.find(x=>x.id===id);
  if(!request)return;
  const users=read(K.users,[]),owner=users.find(u=>u.id===request.userId);
  const items=read(K.items,[]).filter(i=>i.status!=='Devolvido');
  const ordered=[...items].sort((a,b)=>(a.category===request.category?-1:0)-(b.category===request.category?-1:0));
  $('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><div><h3>Registrar recuperação</h3><div class="tiny muted">Vincule a solicitação a um item encontrado e registre a devolução.</div></div><button class="icon-btn" id="closeRecover">${icon('x')}</button></div><div class="record-card"><b class="small">${esc(request.title)}</b><div class="tiny muted">Solicitado por ${esc(owner?.name||'Usuário')} · ${esc(request.category)}</div></div><div class="field"><label>Item encontrado correspondente</label><select id="recoverItem" class="control"><option value="">Selecione um item</option>${ordered.map(i=>`<option value="${i.id}">${esc(i.title)} — ${esc(i.location)}${i.category===request.category?' • mesma categoria':''}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>Data da devolução</label><input id="recoverDate" type="date" class="control" value="${today()}"></div><div class="field"><label>Documento (opcional)</label><input id="recoverDoc" class="control" placeholder="RA ou documento"></div></div><div class="field"><label>Observações</label><textarea id="recoverNotes" class="control" placeholder="Informações relevantes sobre a entrega"></textarea></div><div class="row between"><button class="btn secondary" id="cancelRecover">Cancelar</button><button class="btn" id="confirmRecover">Confirmar devolução</button></div></div></div>`;
  $('#closeRecover').onclick=$('#cancelRecover').onclick=closeModal;
  $('#confirmRecover').onclick=()=>{
    const foundId=$('#recoverItem').value,date=$('#recoverDate').value;
    if(!foundId||!date)return toast('Selecione o item encontrado e informe a data.');
    const allItems=read(K.items,[]),found=allItems.find(i=>i.id===foundId);
    if(!found)return toast('Item encontrado não localizado.');
    found.status='Devolvido';
    found.returnInfo={ownerName:owner?.name||'Proprietário',phone:owner?.phone||'',document:$('#recoverDoc').value.trim(),date,notes:$('#recoverNotes').value.trim(),registeredBy:currentUser().id,method:'FATEC',linkedLostId:request.id};
    request.status='Devolvido';request.matchedItemId=found.id;request.returnDate=date;
    write(K.items,allItems);write(K.lost,lost);closeModal();actionSuccessModal({title:'Recuperação registrada com sucesso',subtitle:'A solicitação foi concluída e o item foi marcado como devolvido.',rows:[['Item',found.title],['Proprietário',owner?.name||'Proprietário'],['Data',fmtDate(date)],['Status','Devolvido']],primaryLabel:'Ver histórico',primaryRoute:'admin-history',secondaryLabel:'Itens perdidos',secondaryRoute:'admin-lost'});
  };
}
function editLostModal(id){const a=read(K.lost,[]),i=a.find(x=>x.id===id);if(!i)return;$('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><h3>Editar item perdido</h3><button class="icon-btn" id="clm">${icon('x')}</button></div><div class="field"><label>Título</label><input id="elTitle" class="control" value="${esc(i.title)}"></div><div class="field"><label>Descrição</label><textarea id="elDesc" class="control">${esc(i.description)}</textarea></div><div class="notice"><b>Status atual: ${esc(i.status)}</b><br>Para concluir uma solicitação, use “Registrar recuperação”. Assim a devolução fica vinculada a um item encontrado e entra corretamente no histórico.</div><button class="btn full" id="saveLostEdit" style="margin-top:10px">Salvar alterações</button></div></div>`;$('#clm').onclick=closeModal;$('#saveLostEdit').onclick=()=>{i.title=$('#elTitle').value.trim();i.description=$('#elDesc').value.trim();write(K.lost,a);closeModal();adminLost();toast('Solicitação atualizada.')}}
function adminHistory(){
  const all=read(K.items,[]),returned=all.filter(i=>i.status==='Devolvido'),pending=all.filter(i=>i.status!=='Devolvido'),ratings=read(K.ratings,[]),avg=ratings.length?(ratings.reduce((sum,r)=>sum+r.score,0)/ratings.length).toFixed(1):'—';
  const tab=state.adminHistoryTab||'Devolvidos';
  const methodLabel=m=>m==='DIRECT_USER'?'Direta pelo usuário':m==='FATEC'?'Setor da Fatec':'—';
  const rows=tab==='Devolvidos'?returned.map(i=>{const rs=ratings.filter(x=>x.itemId===i.id),finder=rs.find(r=>(r.perspective||'OWNER')==='FINDER'),owner=rs.find(r=>(r.perspective||'OWNER')==='OWNER'),itemAvg=rs.length?(rs.reduce((s,r)=>s+r.score,0)/rs.length).toFixed(1):null;return `<tr><td><div class="table-item"><div class="table-thumb"><img src="${i.photos[0]}"></div><b>${esc(i.title)}</b></div></td><td>${esc(i.returnInfo?.ownerName||'—')}</td><td>${fmtDate(i.returnInfo?.date)}</td><td>${methodLabel(i.returnInfo?.method)}</td><td>${esc(i.location)}</td><td>${rs.length?`<button class="feedback-summary" data-feedbacks="${i.id}"><b>${itemAvg}/5 ★</b><span>${rs.length} avaliação${rs.length===1?'':'ões'}${finder&&owner?' · 2 perspectivas':''}</span></button>`:'—'}</td></tr>`}).join(''):
  pending.map(i=>`<tr><td><div class="table-item"><div class="table-thumb"><img src="${i.photos[0]}"></div><b>${esc(i.title)}</b></div></td><td>${esc(read(K.users,[]).find(u=>u.id===i.creatorId)?.name||'—')}</td><td>${fmtDate(i.date)}</td><td>${esc(i.status)}</td><td>${esc(i.holder==='FATEC'?'Fatec':'Com o usuário')}</td><td>${esc(i.location)}</td></tr>`).join('');
  const headers=tab==='Devolvidos'?'<th>ITEM</th><th>PROPRIETÁRIO</th><th>DATA DEVOLUÇÃO</th><th>FORMA</th><th>LOCAL ORIGINAL</th><th>FEEDBACK</th>':'<th>ITEM</th><th>REGISTRADO POR</th><th>DATA ENCONTRO</th><th>STATUS</th><th>POSSE ATUAL</th><th>LOCAL</th>';
  const body=`<div class="admin-page-title"><div><h2>Histórico de itens</h2><p>Consulte itens devolvidos e ainda não devolvidos.</p></div><button class="btn secondary sm" id="exportHistoryBtn">${icon('download')} Exportar relatório</button></div><div class="metric-grid"><div class="metric"><span>Total devolvido</span><strong>${returned.length}</strong></div><div class="metric"><span>Não devolvidos</span><strong>${pending.length}</strong></div><div class="metric"><span>Feedbacks recebidos</span><strong>${ratings.length}</strong></div><div class="metric"><span>Média geral</span><strong>${avg}</strong></div></div><div class="admin-history-tabs"><button class="${tab==='Devolvidos'?'active':''}" data-history-tab="Devolvidos">Devolvidos (${returned.length})</button><button class="${tab==='Não devolvidos'?'active':''}" data-history-tab="Não devolvidos">Não devolvidos (${pending.length})</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr>${headers}</tr></thead><tbody>${rows||`<tr><td colspan="6" class="muted" style="text-align:center;padding:24px">Nenhum registro nesta categoria.</td></tr>`}</tbody></table></div>`;
  $('#app').innerHTML=adminLayout('Histórico',body,'admin-history');bindAdmin();
  $$('[data-history-tab]').forEach(b=>b.onclick=()=>{state.adminHistoryTab=b.dataset.historyTab;adminHistory()});
  $$('[data-feedbacks]').forEach(b=>b.onclick=()=>adminFeedbackModal(b.dataset.feedbacks));
  $('#exportHistoryBtn').onclick=exportHistory;
}
function adminFeedbackModal(itemId){
  const i=read(K.items,[]).find(x=>x.id===itemId),rs=read(K.ratings,[]).filter(r=>r.itemId===itemId),users=read(K.users,[]);
  if(!i||!rs.length)return toast('Este item ainda não recebeu avaliações.');
  $('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><div><h3>Feedback da devolução</h3><div class="tiny muted">${esc(i.title)} · ${rs.length} avaliação${rs.length===1?'':'ões'}</div></div><button class="icon-btn" id="closeFeedback">${icon('x')}</button></div>${rs.map(r=>{const who=users.find(u=>u.id===r.userId),pers=(r.perspective||'OWNER')==='FINDER'?'Quem encontrou/devolveu':'Quem perdeu/recuperou';return `<div class="record-card" style="margin-bottom:9px"><div class="row between"><div><b class="small">${pers}</b><div class="tiny muted">${esc(who?.name||'Usuário')}</div></div><span class="badge returned">${r.score}/5 ★</span></div>${r.tags?.length?`<div class="tag-wrap" style="margin-top:8px">${r.tags.map(t=>`<span class="tag active">${esc(t)}</span>`).join('')}</div>`:''}${r.comment?`<div class="tiny muted" style="margin-top:8px;line-height:1.5">${esc(r.comment)}</div>`:''}</div>`}).join('')}<button class="btn secondary full" id="feedbackOk">Fechar</button></div></div>`;
  $('#closeFeedback').onclick=$('#feedbackOk').onclick=closeModal;
}
function exportHistory(){const data=read(K.items,[]);downloadJSON('historico-itens.json',data)}
function adminUsers(){const users=read(K.users,[]),normal=users.filter(u=>u.role==='USER'),admins=users.filter(u=>u.role==='ADMIN');const body=`<div class="admin-page-title"><div><h2>Usuários</h2><p>Gerencie usuários e administradores cadastrados.</p></div><button class="btn sm" id="addAdmin">${icon('plus')} Adicionar administrador</button></div><div class="metric-grid"><div class="metric"><span>Total de usuários</span><strong>${users.length}</strong></div><div class="metric"><span>Usuários comuns</span><strong>${normal.length}</strong></div><div class="metric"><span>Administradores</span><strong>${admins.length}</strong></div><div class="metric"><span>Ativos</span><strong>${users.filter(u=>u.active).length}</strong></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>USUÁRIO</th><th>PERFIL</th><th>TELEFONE</th><th>REGISTROS</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="table-item"><div class="avatar" style="width:30px;height:30px">${initials(u.name)}</div><div><b>${esc(u.name)}</b><span>${esc(u.email)}</span></div></div></td><td>${u.role==='ADMIN'?'Administrador':'Aluno'}</td><td>${esc(u.phone||'—')}</td><td>${read(K.items,[]).filter(i=>i.creatorId===u.id).length+read(K.lost,[]).filter(i=>i.userId===u.id).length}</td><td>${u.active?'<span class="badge returned">Ativo</span>':'<span class="badge rejected">Desativado</span>'}</td><td><div class="table-actions"><button data-toggle-user="${u.id}" ${u.id===currentUser().id?'disabled':''}>${u.active?icon('x','sm'):icon('check','sm')}</button></div></td></tr>`).join('')}</tbody></table></div>`;$('#app').innerHTML=adminLayout('Usuários',body,'admin-users');bindAdmin();$('#addAdmin').onclick=addAdminModal;$$('[data-toggle-user]').forEach(b=>b.onclick=()=>toggleUser(b.dataset.toggleUser))}
function toggleUser(id){const a=read(K.users,[]),u=a.find(x=>x.id===id);if(!u)return;u.active=!u.active;write(K.users,a);adminUsers();toast('Status do usuário atualizado.')}
function addAdminModal(){$('#modal-root').innerHTML=`<div class="admin-modal-backdrop"><div class="admin-modal"><div class="modal-head"><h3>Adicionar administrador</h3><button class="icon-btn" id="ca">${icon('x')}</button></div><div class="field"><label>Nome</label><input id="aaName" class="control"></div><div class="field"><label>E-mail</label><input id="aaEmail" class="control"></div><div class="field"><label>Telefone</label><input id="aaPhone" class="control"></div><div class="field"><label>Senha inicial</label><input id="aaPass" type="password" class="control"></div><button id="saveAdmin" class="btn full">Criar administrador</button></div></div>`;$('#ca').onclick=closeModal;$('#saveAdmin').onclick=async()=>{if(!$('#aaName').value.trim()||!$('#aaEmail').value.trim()||$('#aaPass').value.length<4)return toast('Preencha os dados corretamente.');const a=read(K.users,[]),email=$('#aaEmail').value.trim();if(a.some(u=>norm(u.email)===norm(email)))return toast('Este e-mail já está cadastrado.');a.push({id:'u-admin-'+Date.now(),name:$('#aaName').value.trim(),email,phone:$('#aaPhone').value.replace(/\D/g,''),passwordHash:await hashPassword($('#aaPass').value),role:'ADMIN',course:'Administração',campus:'Fatec Taquaritinga',active:true});write(K.users,a);closeModal();adminUsers();toast('Administrador criado.')}}
function adminSettings(){const s=read(K.settings,{});const body=`<div class="admin-page-title"><div><h2>Configurações</h2><p>Personalize categorias, locais e contato institucional.</p></div><button class="btn sm" id="saveSettings">Salvar alterações</button></div><div class="settings-grid"><div class="admin-card"><div class="admin-card-head"><h3>Categorias de itens</h3><button class="btn secondary sm" id="addCategory">${icon('plus')} Nova categoria</button></div><div class="pill-list" id="catPills">${s.categories.map(c=>`<span class="config-pill">${esc(c)}</span>`).join('')}</div><div class="admin-card-head" style="margin-top:18px"><h3>Locais do campus</h3><button class="btn secondary sm" id="addLocation">${icon('plus')} Novo local</button></div><div>${s.locations.map(x=>`<div class="setting-row"><div><b>${esc(x)}</b><span>Local disponível nos formulários</span></div><span class="badge returned">Ativo</span></div>`).join('')}</div></div><div><div class="admin-card"><h3>Contato do setor</h3><div class="field" style="margin-top:11px"><label>WhatsApp do Achados e Perdidos</label><input id="sectorPhone" class="control" value="${esc(s.sectorWhatsApp)}"></div><div class="notice">Usado quando o item está sob responsabilidade da Fatec.</div></div><div class="admin-card" style="margin-top:12px"><h3>Dados e demonstração</h3><button class="btn secondary full" id="exportBackup" style="margin-top:10px">${icon('download')} Exportar backup</button><label class="btn secondary full" style="margin-top:8px;display:flex;justify-content:center;cursor:pointer">Importar backup<input id="importBackup" type="file" accept="application/json" hidden></label><button class="btn secondary full" id="resetDemo" style="margin-top:8px;color:var(--red)">Restaurar dados iniciais</button></div></div></div>`;$('#app').innerHTML=adminLayout('Configurações',body,'admin-settings');bindAdmin();$('#saveSettings').onclick=()=>{s.sectorWhatsApp=$('#sectorPhone').value.replace(/\D/g,'');write(K.settings,s);toast('Configurações salvas.')};$('#addCategory').onclick=()=>{const n=prompt('Nome da nova categoria:');if(n&&!s.categories.includes(n)){s.categories.push(n);write(K.settings,s);adminSettings()}};$('#addLocation').onclick=()=>{const n=prompt('Nome do novo local:');if(n&&!s.locations.includes(n)){s.locations.push(n);write(K.settings,s);adminSettings()}};$('#exportBackup').onclick=()=>downloadJSON('achaki-backup.json',{users:read(K.users,[]),items:read(K.items,[]),lost:read(K.lost,[]),ratings:read(K.ratings,[]),settings:read(K.settings,{})});$('#importBackup').onchange=importBackupFile;$('#resetDemo').onclick=async()=>{if(!confirm('Restaurar os dados iniciais?'))return;Object.values(K).forEach(k=>localStorage.removeItem(k));await seed();go('home');toast('Dados restaurados.')}}
async function importBackupFile(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.users)||!Array.isArray(data.items)||!Array.isArray(data.lost))throw new Error('invalid');write(K.users,data.users);write(K.items,data.items);write(K.lost,data.lost);write(K.ratings,Array.isArray(data.ratings)?data.ratings:[]);if(data.settings)write(K.settings,data.settings);toast('Backup importado com sucesso.');adminDashboard()}catch{toast('Arquivo de backup inválido.')}finally{e.target.value=''}}
function downloadJSON(name,data){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){closeModal();const r=route();if(r.startsWith('detail/'))return detailPage(r.split('/')[1]);if(r.startsWith('rating/')){const p=r.split('/');return ratingPage(p[1],p[2]||'owner');}if(r==='home')return homePage();if(r==='login')return loginPage();if(r==='register')return registerPage();if(r==='forgot')return forgotPage();if(r==='found')return foundPage();if(r==='lost')return lostPage();if(r==='records')return recordsPage();if(r==='profile')return profilePage();if(r==='admin-dashboard')return adminDashboard();if(r==='admin-found')return adminFound();if(r==='admin-lost')return adminLost();if(r==='admin-history')return adminHistory();if(r==='admin-users')return adminUsers();if(r==='admin-settings')return adminSettings();go('home')}
window.addEventListener('hashchange',render);window.addEventListener('DOMContentLoaded',async()=>{await seed();render()});
